"use client";
import { Tooltip, type TooltipProps } from "./Tooltip";
import styles from "./Tooltip.module.css";
export function InfoTooltip({
  label,
  ...props
}: Omit<TooltipProps, "children"> & { label: string }) {
  return (
    <Tooltip {...props}>
      <button
        type="button"
        className={`${styles.info} inline-grid place-items-center w-5 h-5 p-0 [border:1px_solid_var(--color-tooltip-border-3)] rounded-[50%] text-body [background:transparent] [font:700_11px_var(--font-plus-jakarta),_sans-serif] cursor-pointer css-hover:[background:var(--color-tooltip-background-12)] [&[aria-expanded='true']]:[background:var(--color-tooltip-background-12)] css-hover:text-foreground [&[aria-expanded='true']]:text-foreground`}
        aria-label={label}
        aria-expanded={false}
      >
        i
      </button>
    </Tooltip>
  );
}
